// Audit every workflow in this n8n for the same holes Flowscope shows in 3D.
const KEYS = [/sk-(?:proj-)?[A-Za-z0-9_-]{24,}/, /sk-ant-[A-Za-z0-9_-]{20,}/, /[sr]k_live_[A-Za-z0-9]{16,}/, /AKIA[0-9A-Z]{16}/, /gh[pousr]_[A-Za-z0-9]{30,}/, /AIza[0-9A-Za-z_-]{35}/, /apify_api_[A-Za-z0-9]{20,}/, /xox[bp]-[A-Za-z0-9-]{20,}/];
const ACTION = /gmail|slack|googleSheets|airtable|notion|postgres|supabase|telegram|discord|httpRequest|hubspot|microsoftOutlook/i;
const lines = []; let total = 0;
for (const item of $input.all()) {
  const wf = item.json; const nodes = wf.nodes || []; const out = [];
  for (const n of nodes) {
    const p = JSON.stringify(n.parameters || {});
    if (KEYS.some(r => r.test(p))) out.push(`Key typed straight into node "${n.name}". Move it into a credential and rotate it.`);
    if (/\.webhook$/i.test(n.type) && !n.disabled && (!n.parameters?.authentication || n.parameters.authentication === 'none')) out.push(`Webhook "${n.name}" has no authentication. Anyone with the URL can run this workflow.`);
  }
  const conns = wf.connections || {};
  for (const [from, c] of Object.entries(conns)) for (const group of (c.ai_tool || [])) for (const t of group) {
    const tool = nodes.find(n => n.name === from);
    if (tool && ACTION.test(tool.type)) out.push(`AI agent "${t.node}" can use "${from}" on its own. Add a human approval step for actions that send or change things.`);
  }
  if (wf.active && !wf.settings?.errorWorkflow) out.push('No error workflow. If this breaks, nobody hears about it.');
  if (out.length) { total += out.length; lines.push(`${wf.name}${wf.active ? '' : ' (inactive)'}\n` + out.map(o => '  - ' + o).join('\n')); }
}
const text = total ? `Flowscope checked ${$input.all().length} workflows and found ${total} things to fix:\n\n${lines.join('\n\n')}\n\nPaste any workflow into Flowscope to see it in 3D with step-by-step fixes.` : `Flowscope checked ${$input.all().length} workflows. All clear.`;
return [{ json: { total, subject: total ? `Flowscope: ${total} things to fix in your n8n` : 'Flowscope: your n8n is all clear', text } }];
